def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    bar_row = next((r for r in range(h) if all(x == 2 for x in grid[r])), None)
    bar_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)

    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != 2]
    if not points:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]

    if bar_row is not None:
        minr = min(r for r, c, v in points)
        maxr = max(r for r, c, v in points)
        if minr > bar_row:
            shift = bar_row + 1 - minr
            marker = maxr + shift + 1
        else:
            shift = bar_row - 1 - maxr
            marker = minr + shift - 1
        for r, c, v in points:
            out[r][c] = bg
        for r, c, v in points:
            out[r + shift][c] = v
        if 0 <= marker < h:
            out[marker] = [8] * w

    elif bar_col is not None:
        minc = min(c for r, c, v in points)
        maxc = max(c for r, c, v in points)
        if minc > bar_col:
            shift = bar_col + 1 - minc
            marker = maxc + shift + 1
        else:
            shift = bar_col - 1 - maxc
            marker = minc + shift - 1
        for r, c, v in points:
            out[r][c] = bg
        for r, c, v in points:
            out[r][c + shift] = v
        if 0 <= marker < w:
            for r in range(h):
                out[r][marker] = 8

    return out
